when.condition:
@{
                if (context.Request.Method != "POST" || context.Request.Body == null) {
                    return false;
                }
                try {
                    var body = context.Request.Body.As<JToken>(preserveContent: true);
                    return body == null || body.Type != JTokenType.Object
                        || body["method"]?.Type != JTokenType.String
                        || (string)body["method"] == "tools/call";
                }
                catch (Newtonsoft.Json.JsonReaderException) {
                    context.Trace("Malformed MCP JSON; applying the tool limit before MCP validation.");
                    return true;
                }
            }
